def orbit(r,c,n=30):
    seen={(r,c)}; stack=[(r,c)]
    while stack:
        a,b=stack.pop()
        nxt=[(b,a)]
        if 2<=a<n: nxt.append((n+1-a,b))
        if 2<=b<n: nxt.append((a,n+1-b))
        for q in nxt:
            if 0<=q[0]<n and 0<=q[1]<n and q not in seen:
                seen.add(q); stack.append(q)
    return seen
