def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]
    for r in range(n):
        for c in range(len(grid[r])):
            if grid[r][c] != 6:
                continue
            seen = {(r, c)}
            queue = deque([(r, c)])
            value = None
            while queue and value is None:
                i, j = queue.popleft()
                if grid[i][j] != 6:
                    value = grid[i][j]
                    break
                neighbors = [(j, i)]
                if i >= 2:
                    neighbors.append((n + 1 - i, j))
                if j >= 2:
                    neighbors.append((i, n + 1 - j))
                for q in neighbors:
                    if 0 <= q[0] < n and 0 <= q[1] < len(grid[q[0]]) and q not in seen:
                        seen.add(q)
                        queue.append(q)
            if value is not None:
                out[r][c] = value
    return out
